 "company-profile.html": {
  "name": "Company Profile",
  "blocks": [
   {
    "key": "company-profile.kick1",
    "tag": "div",
    "text": "Who we are"
   },
   {
    "key": "company-profile.head2",
    "tag": "h2",
    "text": "Fresh produce supply with purpose behind it"
   },
   {
    "key": "about.p1",
    "tag": "p",
    "text": "First Nation Fresh Foods Pty Ltd is a proudly Aboriginal-owned Western Australian company supplying fresh fruit and vegetables, hand-processed produce and chef-prepared value-added foods."
   },
   {
    "key": "about.p2",
    "tag": "p",
    "text": "We operate from Malaga in partnership with an established Western Australian processing business, so buyers get the social value of Indigenous procurement together with the infrastructure, certification and reliability of an operation that has supplied this state for more than thirty years."
   },
   {
    "key": "about.p3",
    "tag": "p",
    "text": "Our purpose is simple: create lasting opportunity for First Nations people and communities, while delivering produce our customers can depend on."
   },
   {
    "key": "company-profile.kick3",
    "tag": "div",
    "text": "Our commitment"
   },
   {
    "key": "company-profile.head4",
    "tag": "h2",
    "text": "Indigenous ownership that reaches further than a certificate"
   },
   {
    "key": "commit.intro",
    "tag": "p",
    "text": "Genuine Aboriginal ownership, with the commitments to employment, training, partnership and community that go with it."
   },
   {
    "key": "company-profile.cardh5",
    "tag": "h3",
    "text": "Aboriginal-owned"
   },
   {
    "key": "company-profile.cardp6",
    "tag": "p",
    "text": "First Nation Fresh Foods is genuinely Aboriginal-owned and led. Buyers working with us support an Indigenous enterprise directly."
   },
   {
    "key": "company-profile.cardh7",
    "tag": "h3",
    "text": "Training and leadership"
   },
   {
    "key": "company-profile.cardp8",
    "tag": "p",
    "text": "Supporting Indigenous employment, training, leadership and business development as the business grows."
   },
   {
    "key": "company-profile.cardh9",
    "tag": "h3",
    "text": "Communities and growers"
   },
   {
    "key": "company-profile.cardp10",
    "tag": "p",
    "text": "Building strong and respectful partnerships with First Nations communities, growers and businesses."
   },
   {
    "key": "company-profile.cardh11",
    "tag": "h3",
    "text": "Our own product range"
   },
   {
    "key": "company-profile.cardp12",
    "tag": "p",
    "text": "Developing a proudly Indigenous product range and brand, including foods made with native Australian ingredients."
   },
   {
    "key": "company-profile.kick13",
    "tag": "div",
    "text": "Procurement value"
   },
   {
    "key": "company-profile.head14",
    "tag": "h2",
    "text": "Supporting Indigenous procurement commitments"
   },
   {
    "key": "commit.p1",
    "tag": "p",
    "text": "Government agencies and corporate buyers increasingly carry Aboriginal procurement commitments. Working with First Nation Fresh Foods lets those commitments be met through a supplier with the certification, cool-chain infrastructure and delivery capability that institutional supply demands."
   },
   {
    "key": "commit.p2",
    "tag": "p",
    "text": "Buyers do not have to choose between social value and operational reliability."
   },
   {
    "key": "company-profile.kick16",
    "tag": "div",
    "text": "Heritage"
   },
   {
    "key": "company-profile.head17",
    "tag": "h2",
    "text": "From a small Cannington unit to purpose-built cool-chain processing"
   },
   {
    "key": "company-profile.lead15",
    "tag": "p",
    "text": "The processing operation we work through has supplied Western Australian kitchens since 1993."
   },
   {
    "key": "profile.t1h",
    "tag": "b",
    "text": "Beginnings in Cannington"
   },
   {
    "key": "profile.t1p",
    "tag": "p",
    "text": "Operations began in a small unit in Cannington, supplying wholesale fruit and vegetables and hand and machine processed produce to a niche hospitality market."
   },
   {
    "key": "profile.t2h",
    "tag": "b",
    "text": "Canning Vale Markets"
   },
   {
    "key": "profile.t2p",
    "tag": "p",
    "text": "Relocation to the Canning Vale Markets, cutting transport costs and building direct grower and market agent relationships."
   },
   {
    "key": "profile.t3h",
    "tag": "b",
    "text": "Market retail operation"
   },
   {
    "key": "profile.t3p",
    "tag": "p",
    "text": "A fruit and vegetable retail operation at the markets lifted stock levels and sped up produce turnover."
   },
   {
    "key": "profile.t4h",
    "tag": "b",
    "text": "Purpose-built premises"
   },
   {
    "key": "profile.t4p",
    "tag": "p",
    "text": "A move into purpose-built food processing and warehouse premises close to the Perth Metropolitan Markets, with daily market and grower access."
   },
   {
    "key": "profile.t5h",
    "tag": "b",
    "text": "First Nation Fresh Foods"
   },
   {
    "key": "profile.t5p",
    "tag": "p",
    "text": "First Nation Fresh Foods Pty Ltd established at Malaga, bringing Aboriginal-owned fresh and value-added food supply to WA buyers."
   },
   {
    "key": "company-profile.kick19",
    "tag": "div",
    "text": "Infrastructure"
   },
   {
    "key": "company-profile.head20",
    "tag": "h2",
    "text": "What sits behind every order"
   },
   {
    "key": "company-profile.tilth21",
    "tag": "h3",
    "text": "12 cool rooms"
   },
   {
    "key": "company-profile.tiltp22",
    "tag": "p",
    "text": "Twelve separate cool rooms running different temperatures for different produce, plus two freezer rooms and two blast chillers."
   },
   {
    "key": "company-profile.tilth23",
    "tag": "h3",
    "text": "14 refrigerated vehicles"
   },
   {
    "key": "company-profile.tiltp24",
    "tag": "p",
    "text": "A dedicated refrigerated delivery service with purpose-built cooled loading docks, running fourteen trucks and express vans."
   },
   {
    "key": "company-profile.tilth25",
    "tag": "h3",
    "text": "6 chefs and cooks"
   },
   {
    "key": "company-profile.tiltp26",
    "tag": "p",
    "text": "Six professional chefs and cooks on staff, providing product development and technical support to customers."
   },
   {
    "key": "company-profile.kick27",
    "tag": "div",
    "text": "Sourcing"
   },
   {
    "key": "company-profile.head28",
    "tag": "h2",
    "text": "Daily access to the market floor"
   },
   {
    "key": "profile.sourcing",
    "tag": "p",
    "text": "Being located close to the Perth Metropolitan Markets lets us source produce directly on any given day, supported by grower-supplied produce accessed daily. What reaches your kitchen is as close to harvest as the supply chain allows."
   }
  ]
 },
