 "facilities.html": {
  "name": "Facilities",
  "blocks": [
   {
    "key": "facilities.kick1",
    "tag": "div",
    "text": "Cool chain"
   },
   {
    "key": "facilities.head2",
    "tag": "h2",
    "text": "Twelve cool rooms, twelve temperature profiles"
   },
   {
    "key": "fac.p1",
    "tag": "p",
    "text": "Different produce respires at different rates and needs different handling. We operate twelve separate cool rooms running different temperatures so each line is held where it should be, rather than averaged across one chiller."
   },
   {
    "key": "fac.p2",
    "tag": "p",
    "text": "Two freezer rooms and two blast chillers support frozen lines and rapid chilling of prepared product, protecting shelf life for longer regional and remote runs."
   },
   {
    "key": "facilities.kick4",
    "tag": "div",
    "text": "Inside the facility"
   },
   {
    "key": "facilities.head5",
    "tag": "h2",
    "text": "Facility videos"
   },
   {
    "key": "facilities.lead3",
    "tag": "p",
    "text": "Walk-throughs of the cool-chain and despatch operation."
   },
   {
    "key": "facilities.kick6",
    "tag": "div",
    "text": "Logistics"
   },
   {
    "key": "facilities.head7",
    "tag": "h2",
    "text": "A refrigerated fleet and cooled docks"
   },
   {
    "key": "fac.p3",
    "tag": "p",
    "text": "Orders are picked from the cool rooms into purpose-built cooled loading docks, then onto our own refrigerated delivery service &mdash; fourteen refrigerated trucks and express vans."
   },
   {
    "key": "fac.p4",
    "tag": "p",
    "text": "Running our own fleet means the cool chain stays unbroken and delivery windows stay ours to manage, across metropolitan, regional and remote Western Australia."
   }
  ]
 },
